    "question": "على أي أساس تقوم الإدارة المالية في أمريكا بتقدير واحتساب مبالغ رسوم الوكالة لكل دولة؟",
    "answer": "أهلاً بك يا فندم. يعتمد القسم المالي على مصفوفة تقييم دولية ذكية ومحوكمة؛ حيث يتم الاحتساب بناءً على حجم التبادل التجاري السنوي للدولة، عدد الموانئ البحرية والمطارات الجوية النشطة، وإحصائيات حجم شركات الشحن، الاستيراد، والتصدير العاملة في هذا النطاق."
