    "answer": "أهلاً ومرحباً بك يا فندم. تمنح المجلة وكلاءها نظام عوائد هو الأقوى عالمياً؛ حيث يحصل الوكيل على نسبة مئوية مجزية ومحفزة تتراوح بين 50% وتصل إلى 70% من قيمة الإعلانات والرعايات المحلية التي يبرمها في سوقه، وتتحدد النسبة الدقيقة حسب حجم الباقة الإعلانية ومجهود التسويق."
