    "answer": "سؤال ذكي جداً يا فندم. الإجابة هي لا؛ الوكيل المحلي لا يتحمل أي مصاريف نهائياً مقابل الترجمة. الإدارة المركزية في الولايات المتحدة الأمريكية تتحمل بالكامل كافة تكاليف الترجمة الاحترافية والرفع والتدقيق الفني بفضل الأنظمة البرمجية المتطورة المدمجة بالموقع بـ 12 لغة."
