    "answer": "مرحباً بك يا فندم. هذا الأمر غير متاح تقنياً أو قانونياً؛ يجب أن تتم كافة التحويلات المالية من الحساب البنكي الرسمي لشركة الوكيل مباشرة إلى الحساب البنكي الفيدرالي للمجلة في أمريكا بالدولار الأمريكي لضمان الامتثال للأنظمة المالية."
