    "answer": "أهلاً بك يا فندم، كن على ثقة تامة بحقوقك. يتم تجميع وتصفية كافة الحصص المالية والعمولات الخاصة بالوكيل إلكترونياً وبشكل دوري نهاية كل شهر ميلادي، وتحول مباشرة إلى حسابك البنكي الرسمي بعد خصم المصاريف الإدارية والبنكية القياسية للتحويل الدولي."
