    "answer": "نعم، بكل تأكيد يا فندم! يُعد الدليل الدولي من أقوى مصادر الدخل للوكيل؛ حيث تحصل على النسبة التجارية والتنافسية المتفق عليها في عقدك من قيمة أي اشتراك مدفوع لشركة شحن أو تخليص تقع داخل حدود نطاقك الجغرافي المسجل."
