    "answer": "مرحباً بك يا فندم. نعم، تشمل الوكالة الحصرية للدولة وبشكل كامل كافة المناطق الاقتصادية الخاصة، المناطق الحرة، الموانئ البحرية، المطارات الجوية، والمنافذ البرية الواقعة جغرافياً وسياسياً داخل الحدود الرسمية للدولة المذكورة في العقد."
