    "question": "هل يلتزم مكتب الوكيل بتقديم تقارير دورية للإدارة المركزية حول حركة المبيعات والمفاوضات الجارية؟",
    "answer": "نعم يا فندم. يلتزم الوكيل برفع تقرير تشغيلي وتسويقي دوري (شهري) عبر لوحة التحكم الخاصة به؛ يوضح التقرير حجم المفاوضات الجارية (Pipeline)، الشركات المسجلة، والمستهدفات المحققة، لتمكين قطاع التوسع الدولي من تقييم الأداء وتقديم الدعم الفني والتسويقي اللازم."
