    "answer": "أهلاً بك يا فندم، عقودكم محمية تماماً. تلتزم المجلة التزاماً قانونياً بالأسعار الموقعة في العقود الجارية حتى انتهاء مدتها الزمنية دون أي زيادة؛ وأي تحديث أو مراجعة لأسعار الباقات يتم الإعلان عنه بشفافية في بداية كل عام ميلادي جديد فقط."
