    "answer": "مرحباً بكم يا فندم ويسعدنا التعاون مع وكالات الدعاية. نعم، تمنح المجلة وكالات الدعاية والإعلان الخارجية المعتمدة عمولة تجارية قياسية متميزة تتراوح بين 15% إلى 20% من قيمة الحملة الإعلانية المقبولة والمدفوعة، ويتم تسويتها فور تحصيل الفاتورة."
