    "answer": "أهلاً بك يا فندم، نؤكد لك عدم وجود أي مصاريف خفية. الترجمة لكافة اللغات الدولية الـ 12 المعتمدة في منصتنا (بما فيها الصينية، الروسية، الألمانية، واليابانية) مدمجة بالكامل ومجانية ضمن تكلفة الباقة المحجوزة ولا يتم فرض أي سنت إضافي عليها."
