    "answer": "مرحباً بك يا فندم. يتم برميّاً إرسال إشعار وتنبيه بالدفع؛ وفي حال عدم السداد خلال 10 أيام عمل، يقوم النظام بإيقاف ظهور البنر الإعلاني مؤقتاً لحين تسوية المستحقات، مع حفظ وإعادة تفعيل المدة المتبقية لك فور السداد دون المساس بسلامة العقد."
