    "answer": "يرجى الانتباه والالتزام الصارم بهذا البند يا فندم؛ يحظر تماماً بموجب ميثاق الشرف الإعلامي والقوانين الأمريكية قبول أي هدايا، منافع، أو مبالغ مادية لتوجيه المحتوى. وأي مراسل يثبت تورطه في ذلك يتم فصله فوراً، سحب اعتماده، وملاحقته قانونياً بتهمة الإضرار بالمنصة ونزاهتها الدولية."
