    "answer": "مرحباً بك يا فندم. التكريمات مفتوحة لكافة الفئات والرتب والدرجات الوظيفية؛ حيث تشمل مفتشي الجمارك الميدانيين، موظفي بوابات الموانئ والمطارات، الإداريين، والقيادات العليا الذين حققوا إنجازات استثنائية وبطولية في حماية الحدود، تسهيل حركة التجارة العادلة، أو ضبط وإحباط عمليات التهريب الدولية، ويتم إبراز جهودهم بـ 12 لغة."
