    "question": "لمن يجب أن نوجه شكوانا الرسمية في حال واجهنا تقصيراً أو سوء معاملة من قِبل الوكيل المحلي في بلدنا؟",
    "answer": "مرحباً بك يا فندم، ونحن نأخذ هذا الأمر بحزم شديد. يمكنك رفع شكواك مباشرة إلى (إدارة الامتثال والجودة بالمركز الرئيسي في أمريكا) عبر استمارة الشكاوى بالموقع، أو المراسلة الفورية للبريد المحمي المباشر: compliance@gmarikmagazine.com، وسيتم التحقيق الفوري والميداني في الواقعة لضمان جودة الخدمة."
