    "question": "ما هو الإجراء المتبع إذا تم رفض طلبي للانضمام كمراسل أو للتسجيل في الدليل الدولي؟",
    "answer": "أهلاً بك يا فندم. يقوم النظام برميّاً بإرسال إشعار رسمي عبر بريدك يتضمن توضيحاً تقنياً أو قانونياً دقيقاً للأسباب التي أدت للرفض؛ ويمنحك النظام فترة سماح مرنة لتعديل البيانات، أو استكمال الوثائق والنواقص المذكورة وإعادة إرسال الطلب لفحصه وتفعيله من جديد."
