    "answer": "مرحباً بك يا فندم. يدمج موقعنا خوارزمية ذكية لفرز وتصنيف اللغات (Language Classifier)؛ بمجرد وصول رسالتك بأي لغة، يقوم النظام آلياً بتحويلها إلى المترجم والمحرر المختص بتلك اللغة تحديداً من بين اللغات الـ 12 المعتمدة لدينا، لضمان قراءتها وفهمها والرد عليها بنفس لغتك الأصلية."
