    "question": "ما هي رسالة وكلمة فريق العمل لكل مستخدم أو معلن يشعر بالضيق بسبب تأخر الرد؟",
    "answer": "أهلاً بك يا فندم. رسالتنا لسيادتكم هي: \"ثقتكم هي رأس مالنا الإستراتيجي. نحن نعمل بموجب شروط وحوكمة قانونية أمريكية صارمة لضمان جودة وموثوقية المعاملات العابرة للحدود. نشكر لكم وافر صبركم وتفهمكم، ونؤكد أن فريقنا يبذل أقصى جهوده الفنية لخدمتكم وحماية حقوقكم بـ 12 لغة عالمية\"."
