    "answer": "مرحباً بك يا فندم. يتيح لك الموقع ميزة الخدمة الذاتية عبر صفحة \"تتبع حالة التذكرة\"؛ حيث يمكنك الدخول وإدخال كود التتبع الذي تسلمته في بريدك، ليظهر لك النظام فوراً وبـ 12 لغة المرحلة الحالية لطلبك والاسم الإداري للقسم الفاحص له."
