    "answer": "أهلاً بك يا فندم. نرجو من سيادتكم أولاً مراجعة فولدر الرسائل غير المرغوب فيها (Spam/Junk Folder)؛ فقد تكون الإدارة أرسلت لك طلباً عاجلاً لاستكمال مستند ناقص، وفي حال عدم وجوده، يمكنك فتح تذكرة دعم عاجلة ليتولى المهندسون تنشيط الحساب فوراً."
