    "answer": "مرحباً بك يا فندم. موظفو الدعم التقني متخصصون فقط في حل الأعطال البرمجية والبرمجة؛ وفي حال استفساركم عن الأسعار، يقوم النظام آلياً بتوجيه وتحويل تذكرتكم إلى قسم المبيعات التجاري الدولي للإجابة على سيادتكم بالباقات الرسمية بـ 12 لغة."
