    "answer": "أهلاً بك يا فندم. الإدارة المركزية تعمل بموجب توقيت شرق أمريكا (EST)، ولكن لحماية انسيابية الأعمال الدولية، يعمل فريق الدعم والفرز الفني في مصفوفة شيفتات متناوبة تغطي الـ 24 ساعة طوال أيام الأسبوع (24/7)، لضمان الإجابة على استفساراتكم بـ 12 لغة دون تأثر بفروق الوقت."
