    "answer": "أهلاً بك يا فندم. نعم، يتيح النظام لشركائنا الكرام ومستثمري الباقات الذهبية والبلاتينية ميزة جدولة وحجز اجتماع تقني مباشر عبر برنامج زووم (Zoom) مع مهندسي الدعم؛ للدخول معكم ومراجعة وحل أي مشكلة برمجية معقدة في حسابكم بشكل فوري ومباشر."
