    "question": "لقد أرسلت طلباً للحصول على التكريم عبر رسائل حساب المجلة على الفيسبوك ولم يتم الرد، ما السبب؟",
    "answer": "مرحباً بك يا فندم. حسابات المجلة على منصات التواصل الاجتماعي مخصصة فقط لبث الأخبار وقصص النجاح؛ ولا تملك صلاحية استقبال أو فحص وثائق التكريمات أو اشتراكات الدليل لعدم أمانها. الحوكمة الرقمية تشترط دائماً التقديم الرسمي والأمن عبر النماذج المشفرة داخل الموقع الإلكتروني حصرياً."
