// ==================== دمج كل القواعد في قائمة واحدة للمطابقة ====================
const allEntries = [...greetings, ...faqData];

// ==================== أدوات تطبيع النص العربي ====================
function normalizeArabic(text) {
  if (!text) return "";
  return text
    .toString()
    .trim()
    .toLowerCase()
    .replace(/[\u064B-\u065F\u0670]/g, "") // إزالة التشكيل
    .replace(/[إأآا]/g, "ا")
    .replace(/ى/g, "ي")
    .replace(/ة/g, "ه")
    .replace(/ؤ/g, "و")
    .replace(/ئ/g, "ي")
    .replace(/[^\u0621-\u064A0-9a-z\s]/g, " ") // إزالة علامات الترقيم
    .replace(/\s+/g, " ")
    .trim();
}

function tokenize(text) {
  return normalizeArabic(text).split(" ").filter(Boolean);
}

// ==================== محرك المطابقة الدلالية ====================
/**
 * findBestMatch: يبحث في كل الأسئلة والكلمات المفتاحية عن أقرب تطابق
 * لرسالة المستخدم، ويرجع أفضل نتيجة مع درجة الثقة.
 */
function findBestMatch(userMessage) {
  const userTokens = tokenize(userMessage);
  if (userTokens.length === 0) return null;

  let bestEntry = null;
  let bestScore = 0;

  for (const entry of allEntries) {
    let score = 0;

    // 1) مطابقة الكلمات المفتاحية (وزن أعلى)
    for (const kw of entry.keywords || []) {
      const kwTokens = tokenize(kw);
      const kwJoined = kwTokens.join(" ");
      const userJoined = userTokens.join(" ");
      if (kwJoined && userJoined.includes(kwJoined)) {
        score += 3 * kwTokens.length; // تطابق عبارة كاملة
      } else {
        for (const kt of kwTokens) {
          if (userTokens.includes(kt)) score += 1;
        }
      }
    }

    // 2) مطابقة كلمات نص السؤال نفسه (وزن أقل)
    const questionTokens = tokenize(entry.question);
    for (const t of userTokens) {
      if (questionTokens.includes(t)) score += 0.5;
    }

    if (score > bestScore) {
      bestScore = score;
      bestEntry = entry;
    }
  }

  if (!bestEntry || bestScore < 1) return null;

  return {
    id: bestEntry.id,
    question: bestEntry.question,
    answer: bestEntry.answer,
    score: bestScore
  };
}

// ==================== الرد الافتراضي عند عدم وجود تطابق ====================
const fallbackResponse =
  "أهلاً بك يا فندم 🌹، لم أتمكن من العثور على إجابة دقيقة لاستفسارك ضمن قاعدة بياناتنا الحالية. " +
  "يمكنك إعادة صياغة سؤالك بشكل مختلف، أو فتح تذكرة دعم فني وسيتواصل معك فريق خدمة العملاء البشري " +
  "بمجلة \"جمارك مجازين\" في أقرب وقت لمساعدتك.";

/**
 * getResponse: نقطة الدخول الرئيسية لمحرك الشات بوت
 * تستقبل رسالة المستخدم وترجع نص الرد المناسب مباشرة
 */
function getResponse(userMessage) {
  const match = findBestMatch(userMessage);
  if (match) {
    return match.answer;
  }
  return fallbackResponse;
}

/**
 * getResponseDetailed: نفس الوظيفة أعلاه لكن ترجع كائن كامل
 * (مفيد لعرض معرّف السؤال المطابق أو درجة الثقة في واجهة الإدارة)
 */
function getResponseDetailed(userMessage) {
  const match = findBestMatch(userMessage);
  if (match) {
    return {
      matched: true,
      id: match.id,
      matchedQuestion: match.question,
      answer: match.answer,
      confidence: match.score
    };
  }
  return {
    matched: false,
    id: null,
    matchedQuestion: null,
    answer: fallbackResponse,
    confidence: 0
  };
}

// ==================== إعدادات تعدد اللغات (12 لغة المطابقة لموقع الإندكس) ====================
const SUPPORTED_LANGS = ["ar", "en", "zh", "es", "de", "fr", "tr", "ja", "ko", "el", "it", "ru"];
const GOOGLE_LANG_MAP = { zh: "zh-CN" }; // نفس التطويع المستخدم في index.html

// يقرأ اللغة الحالية للموقع من نفس المفتاح اللي بيستخدمه الإندكس (gmarik_lang)
function getCurrentLang() {
  try {
    const lang = localStorage.getItem("gmarik_lang");
    return SUPPORTED_LANGS.includes(lang) ? lang : "ar";
  } catch (e) {
    return "ar";
  }
}

const chatbotTranslationCache = {};

// ترجمة نص عربي (رد البوت) إلى لغة الموقع الحالية
async function translateChatbotText(text, targetLang) {
  if (!text || targetLang === "ar") return text;
  const cacheKey = "to_" + targetLang + "::" + text;
  if (chatbotTranslationCache[cacheKey]) return chatbotTranslationCache[cacheKey];
  try {
    const googleLang = GOOGLE_LANG_MAP[targetLang] || targetLang;
    const url = `https://translate.googleapis.com/translate_a/single?client=gtx&sl=ar&tl=${googleLang}&dt=t&q=${encodeURIComponent(text)}`;
    const res = await fetch(url);
    if (!res.ok) throw new Error("translate api error");
    const data = await res.json();
    const translated = data[0].map((part) => part[0]).join("");
    chatbotTranslationCache[cacheKey] = translated;
    return translated;
  } catch (err) {
    return text; // fallback: يرجع النص العربي لو الترجمة فشلت
  }
}

// ترجمة رسالة المستخدم (بأي لغة من الـ 12) إلى العربية أولاً،
// لأن قاعدة الأسئلة والكلمات المفتاحية كلها مكتوبة بالعربي وعليها تتم المطابقة
async function translateToArabic(text, sourceLang) {
  if (!text || sourceLang === "ar") return text;
  const cacheKey = "from_" + sourceLang + "::" + text;
  if (chatbotTranslationCache[cacheKey]) return chatbotTranslationCache[cacheKey];
  try {
    const url = `https://translate.googleapis.com/translate_a/single?client=gtx&sl=auto&tl=ar&dt=t&q=${encodeURIComponent(text)}`;
    const res = await fetch(url);
    if (!res.ok) throw new Error("translate api error");
    const data = await res.json();
    const translated = data[0].map((part) => part[0]).join("");
    chatbotTranslationCache[cacheKey] = translated;
    return translated;
  } catch (err) {
    return text;
  }
}

// ==================== دوال التحكم في واجهة الشات بوت (الأزرار في index.html) ====================
// هذه الدوال الثلاثة هي اللي كانت مفقودة وسبب عدم استجابة زرار "المساعد الجمركي"
function toggleCustomsChat(event) {
  if (event) event.preventDefault();
  const widget = document.getElementById("chat-widget");
  if (!widget) return;
  widget.classList.toggle("active");
  if (widget.classList.contains("active")) {
    const input = document.getElementById("chat-input");
    if (input) input.focus();
  }
}

function closeCustomsChat(event) {
  if (event) event.preventDefault();
  const widget = document.getElementById("chat-widget");
  if (widget) widget.classList.remove("active");
}

// مدة بقاء الرسالة قبل حذفها التلقائي (ساعة واحدة)
const CHAT_MESSAGE_LIFETIME_MS = 60 * 60 * 1000;

function appendChatMessage(text, sender) {
  const body = document.getElementById("chat-body");
  if (!body) return;
  const msg = document.createElement("div");
  msg.className = "chat-msg " + sender;
  msg.textContent = text;
  body.appendChild(msg);
  body.scrollTop = body.scrollHeight;

  // حذف الرسالة تلقائياً بعد ساعة من إرسالها
  setTimeout(() => {
    if (msg && msg.parentNode) {
      msg.parentNode.removeChild(msg);
    }
  }, CHAT_MESSAGE_LIFETIME_MS);
}

async function submitChatbotQuery(event) {
  if (event) event.preventDefault();
  const input = document.getElementById("chat-input");
  if (!input) return;
  const userText = input.value.trim();
  if (!userText) return;

  const currentLang = getCurrentLang();

  appendChatMessage(userText, "user");
  input.value = "";
  input.disabled = true;

  const body = document.getElementById("chat-body");
  const typingMsg = document.createElement("div");
  typingMsg.className = "chat-msg bot";
  typingMsg.id = "chat-typing-indicator";
  typingMsg.textContent = "...";
  if (body) {
    body.appendChild(typingMsg);
    body.scrollTop = body.scrollHeight;
  }

  try {
    const arabicQuery = await translateToArabic(userText, currentLang);
    const arabicAnswer = getResponse(arabicQuery);
    const finalAnswer = await translateChatbotText(arabicAnswer, currentLang);

    const indicator = document.getElementById("chat-typing-indicator");
    if (indicator) indicator.remove();

    appendChatMessage(finalAnswer, "bot");
  } catch (err) {
    const indicator = document.getElementById("chat-typing-indicator");
    if (indicator) indicator.remove();
    appendChatMessage(getResponse(userText), "bot");
  } finally {
    input.disabled = false;
    input.focus();
  }
}

// ==================== التصدير للاستخدام في Node.js أو المتصفح ====================
if (typeof module !== "undefined" && module.exports) {
  module.exports = {
    greetings,
    faqData,
    allEntries,
    normalizeArabic,
    findBestMatch,
    getResponse,
    getResponseDetailed,
    translateChatbotText,
    translateToArabic,
    getCurrentLang,
    SUPPORTED_LANGS,
    CHAT_MESSAGE_LIFETIME_MS
  };
}

if (typeof window !== "undefined") {
  window.JamarekChatbot = {
    greetings,
    faqData,
    allEntries,
    normalizeArabic,
    findBestMatch,
    getResponse,
    getResponseDetailed,
    translateChatbotText,
    translateToArabic,
    getCurrentLang,
    SUPPORTED_LANGS,
    CHAT_MESSAGE_LIFETIME_MS
  };

  // إتاحة دوال الواجهة عالمياً عشان تشتغل مع onclick="..." الموجودة في index.html
  window.toggleCustomsChat = toggleCustomsChat;
  window.closeCustomsChat = closeCustomsChat;
  window.submitChatbotQuery = submitChatbotQuery;

  // إرسال الرسالة بالضغط على Enter داخل مربع الكتابة
  // + جدولة حذف رسالة الترحيب الثابتة الموجودة أصلاً في HTML بعد ساعة زيها زي باقي الرسايل
  window.addEventListener("DOMContentLoaded", () => {
    const chatInput = document.getElementById("chat-input");
    if (chatInput) {
      chatInput.addEventListener("keypress", (e) => {
        if (e.key === "Enter") submitChatbotQuery(e);
      });
    }

    const chatBody = document.getElementById("chat-body");
    if (chatBody) {
      chatBody.querySelectorAll(".chat-msg").forEach((existingMsg) => {
        setTimeout(() => {
          if (existingMsg && existingMsg.parentNode) {
            existingMsg.parentNode.removeChild(existingMsg);
          }
        }, CHAT_MESSAGE_LIFETIME_MS);
      });
    }
  });
}